// Checks the C# models against fixtures generated by the Rust core
// (client/core/tests/event_fixtures.rs). Strict: unknown members fail, and
// every model member is `required`, so drift in either direction fails.

using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;
using HopOn.Native;

var failures = 0;
void Check(bool ok, string what) { if (!ok) failures++; Console.WriteLine($"{(ok ? "ok  " : "FAIL")} {what}"); }

var strict = new HopOnJson(new JsonSerializerOptions(HopOnJson.Default.Options)
{
    UnmappedMemberHandling = JsonUnmappedMemberHandling.Disallow,
    RespectNullableAnnotations = true,
});

var path = Path.Combine(AppContext.BaseDirectory, "fixtures", "events.json");
using var doc = JsonDocument.Parse(File.ReadAllBytes(path));
var seen = new HashSet<Type>();
foreach (var raw in doc.RootElement.EnumerateArray())
{
    var t = raw.GetProperty("t").GetString();
    try
    {
        var ev = raw.Deserialize(strict.UiEvent);
        Check(ev is not null, $"{t} → {ev?.GetType().Name}");
        if (ev is not null) seen.Add(ev.GetType());
        // Round trip: what we'd write is what Rust wrote.
        var back = JsonSerializer.SerializeToElement(ev!, strict.UiEvent);
        Check(JsonElement.DeepEquals(back, raw), $"{t} round-trips");
    }
    catch (JsonException e)
    {
        Check(false, $"{t}: {e.Message}");
    }
}

// Every C# event type is covered by a fixture (and so exists in Rust).
var declared = typeof(UiEvent).GetCustomAttributes(typeof(JsonDerivedTypeAttribute), false)
    .Cast<JsonDerivedTypeAttribute>().Select(a => a.DerivedType).ToHashSet();
var missing = declared.Except(seen).Select(x => x.Name).ToList();
Check(missing.Count == 0, $"every C# event kind has a Rust sample ({declared.Count} kinds){(missing.Count > 0 ? ": missing " + string.Join(", ", missing) : "")}");

// An unknown event kind must not crash the UI's dispatch: it is an exception
// the caller can catch (HopOnCore logs and skips it).
try { JsonDocument.Parse("{\"t\":\"fromTheFuture\"}").RootElement.Deserialize(HopOnJson.Default.UiEvent); Check(false, "unknown kind rejected"); }
catch (JsonException) { Check(true, "unknown kind rejected with JsonException"); }

MergeTests.Run(Check);

Console.WriteLine(failures == 0 ? "all model checks passed" : $"{failures} check(s) failed");
return failures == 0 ? 0 : 1;
